function sky(ctx) {
  ctx.fillStyle = "#242331";
  ctx.fillRect(WORLD_X0, -20, WORLD_X1 - WORLD_X0, PAGE_H + 40);
  const { G, nx, ny, rgb } = SKY_GRID;
  if (!skyTile) {
    skyTile = document.createElement("canvas"); skyTile.width = nx; skyTile.height = ny;
    const g = skyTile.getContext("2d"), im = g.createImageData(nx, ny);
    for (let i = 0; i < nx * ny; i++) { im.data[i * 4] = rgb[i * 3]; im.data[i * 4 + 1] = rgb[i * 3 + 1]; im.data[i * 4 + 2] = rgb[i * 3 + 2]; im.data[i * 4 + 3] = 255; }
    g.putImageData(im, 0, 0);
  }
  ctx.save();
  ctx.beginPath(); ctx.rect(0, 0, PAGE_W, PAGE_H); ctx.clip();
  ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = "high";
  ctx.drawImage(skyTile, -G / 2, -G / 2, nx * G, ny * G);
  ctx.restore();
}
// four-point sparkle with concave sides
export function sparkle(ctx, x, y, R, col, thin = 0.2) {
  const k = R * thin;
  ctx.beginPath();
  ctx.moveTo(x, y - R);
  ctx.quadraticCurveTo(x + k, y - k, x + R, y);
  ctx.quadraticCurveTo(x + k, y + k, x, y + R);
  ctx.quadraticCurveTo(x - k, y + k, x - R, y);
  ctx.quadraticCurveTo(x - k, y - k, x, y - R);
  ctx.closePath(); ctx.fillStyle = col; ctx.fill();
}
