// ---------- traced backdrop patches ----------
// Where the backdrop is a tangle of airbrushed cloud layers and folded ribbon stripes, it is drawn from outlines
// traced on the source (colour classes of the pre-grade frame, cleaned, smoothed and simplified to ~1 px; the gear,
// plants, signs and people in front were masked out and the shapes continued underneath). Each patch: a page rect, a
// palette (pre-grade inks), polygons [colourIndex, soft, x0, y0, x1, y1, …] and ink lines [width·10, x0, y0, …]
// (skeletons of the source's keylines, stroked as there-and-back rings), all in page px. Rings of one colour are
// filled together (even-odd, so holes work). Soft rings (airbrushed cloud interiors) are painted crisp and then
// again blurred, so neighbouring soft layers melt into each other; hard rings stay crisp.
const patchPaths = new Map();
function ringPath(path, p, k0) {
  // closed ring through the midpoints of the traced vertices (quadratic curves keep the outlines round)
  const n = (p.length - k0) / 2, X = (i) => p[k0 + 2 * (i % n)], Y = (i) => p[k0 + 1 + 2 * (i % n)];
  path.moveTo((X(0) + X(1)) / 2, (Y(0) + Y(1)) / 2);
  for (let i = 1; i <= n; i++) path.quadraticCurveTo(X(i), Y(i), (X(i) + X(i + 1)) / 2, (Y(i) + Y(i + 1)) / 2);
  path.closePath();
}
function patchGroups(T) {
  let G = patchPaths.get(T);
  if (!G) {
    const m = new Map();
    for (const p of T.polys) {
      const key = p[0] * 2 + p[1];
      if (!m.has(key)) m.set(key, { ci: p[0], soft: p[1], path: new Path2D() });
      ringPath(m.get(key).path, p, 2);
    }
    const lines = new Map();
    for (const l of T.lines || []) {
      if (!lines.has(l[0])) lines.set(l[0], new Path2D());
      ringPath(lines.get(l[0]), l, 1);
    }
    G = { groups: [...m.values()].sort((a, b) => b.soft - a.soft || a.ci - b.ci), lines: [...lines.entries()] };
    patchPaths.set(T, G);
  }
  return G;
}
function drawPatch(ctx, T) {
  const [x0, y0, x1, y1] = T.rect, { groups, lines } = patchGroups(T);
  ctx.save();
  ctx.beginPath(); ctx.rect(x0, y0, x1 - x0, y1 - y0); ctx.clip();
  ctx.translate(0.5, 0.5); // traced coordinates are pixel centres
  for (const g of groups) if (g.soft) { ctx.fillStyle = T.cols[g.ci]; ctx.fill(g.path, "evenodd"); }
  ctx.filter = `blur(${T.blur}px)`;
  for (const g of groups) if (g.soft) { ctx.fillStyle = T.cols[g.ci]; ctx.fill(g.path, "evenodd"); }
  ctx.filter = "none";
  ctx.lineJoin = "round"; ctx.lineCap = "round"; ctx.lineWidth = 1.6;
  for (const g of groups) if (!g.soft) { ctx.fillStyle = ctx.strokeStyle = T.cols[g.ci]; ctx.stroke(g.path); ctx.fill(g.path, "evenodd"); }
  ctx.strokeStyle = HC.line;
  for (const [w, path] of lines) { ctx.lineWidth = w / 10; ctx.stroke(path); }
  // variable-width ink strokes [colourIndex, x0, y0, w0·10, x1, y1, w1·10, …]: one round-capped segment per step
  for (const st of T.strokes || []) {
    ctx.strokeStyle = T.cols[st[0]];
    for (let i = 1; i + 5 < st.length; i += 3) {
      ctx.beginPath(); ctx.moveTo(st[i], st[i + 1]); ctx.lineTo(st[i + 3], st[i + 4]);
      ctx.lineWidth = (st[i + 2] + st[i + 5]) / 20; ctx.stroke();
    }
  }
  ctx.restore();
}
// The page is tiled by traced patches, painted in this order (later tiles cover earlier ones where they overlap).
// Each tile first repaints the plain sky over its rect (outside its holes), so the hand-built backdrop and gear
// underneath only show beyond the page edges (the header strip reaches past them) and in the holes (under the nav).
//   TR_TOP  the top band: sky, stars, both ribbons' upper runs, the cloud banks, the right tower's top
//   TR_SL   the left half of the scene          TR_MID  between the designer and the stacks (sky, ribbon ends)
//   TR_DK   the desk centre and under it        TR_SR   the right half of the scene
//   TR_OWL  the colour owl's perch, traced on the 115.6 s frame (where the owl is away): its box top, cloud, ribbon
// The designer (TR_DES) and the headline (TR_HL) are drawn on their own, after the tiles.
//   TR_XL, TR_XR  the artwork beyond the page's left and right edges, which only the header strip shows: traced on the
//          strip itself (median of the 91–94 s frames, mapped back through BANNER_MAP), colour x −426…2 and 2204…2600
const TILES = () => [TR_XL, TR_XR, TR_TOP, TR_SL, TR_MID, TR_DK, TR_SR, TR_OWL];
function tileBase(ctx, T) {
  const [x0, y0, x1, y1] = T.rect;
  ctx.save();
  ctx.beginPath(); ctx.rect(x0, y0, x1 - x0, y1 - y0);
  for (const h of T.holes || []) { ctx.moveTo(h[0], h[1]); for (let i = 2; i < h.length; i += 2) ctx.lineTo(h[i], h[i + 1]); ctx.closePath(); }
  ctx.clip("evenodd");
  sky(ctx);
  ctx.restore();
}
function tiles(ctx, base = true) { for (const T of TILES()) { if (base) tileBase(ctx, T); drawPatch(ctx, T); } }

// ---------- headline ----------
// "Mixing down, / late at night.": chunky retro lettering, cream with "late" golden, dark keylines, over a stacked
// extrusion stepping down-right (orange, then magenta-purple). Traced from the source at 117.4 s (TR_HL); the
// beanie showing between the letters is the designer's (drawn under it).
function headline(ctx) { drawPatch(ctx, TR_HL); }

// ---------- nav rail ----------
export const NAV = [
  // label, dot colour, sub, pill x0, x1
  ["objects", "#e8603f", "instruments · tools · spares", 1532, 1710],
  ["radio", "#d8338c", "live · archive · zine", 1726, 1862],
  ["store", "#6a4fb0", "cart · offers · gift", 1878, 1996],
  ["index", "#e9b43a", "manuals · support", 2022, 2161],
];
function nav(ctx) {
  ctx.save();
  // brand: quartered disc (orange top-right, magenta bottom-right, lavender-blue bottom-left, gold top-left; sampled)
  // with a cream pill, and the wordmark
  ctx.save(); ctx.translate(41, 39);
  const q = ["#e0784f", "#b8438f", "#8583b6", "#e2a55a"];
  for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, 17, -Math.PI / 2 + (i * Math.PI) / 2, (i * Math.PI) / 2); ctx.closePath(); ctx.fillStyle = q[i]; ctx.fill(); }
  ctx.beginPath(); ctx.arc(0, 0, 18, 0, TAU); ctx.lineWidth = 3.5; ctx.strokeStyle = HC.cream; ctx.stroke();
  ctx.restore();
  rrect(ctx, 58, 18, 22, 42, 11, HC.cream, 0);
  ctx.font = "600 21px Poppins"; ctx.fillStyle = withAlpha("#f6ecd6", 0.72);
  ctx.fillText("sōko", 95, 34); ctx.fillText("objects", 95, 56);
  // pills
  for (const [label, dot, sub, x0, x1] of NAV) {
    const y0 = 16, h = 42;
    ctx.beginPath(); ctx.roundRect(x0, y0, x1 - x0, h, h / 2);
    ctx.fillStyle = "rgba(34,31,39,0.82)"; ctx.fill();
    // the UI is softer and greyer than the illustration's cream (label peak, outline and sub-label levels sampled)
    ctx.lineWidth = 2.2; ctx.strokeStyle = "rgba(232,224,234,0.55)"; ctx.stroke();
    circle(ctx, x0 + 22, y0 + 21, 10.5, dot, 2.6, "#ecd8d2");
    ctx.font = "600 16.5px Poppins"; ctx.fillStyle = "#e3d3cc"; ctx.fillText(label, x0 + 42, y0 + 20);
    ctx.font = "500 8.5px Poppins"; ctx.fillStyle = "rgba(232,224,228,0.36)"; ctx.fillText(sub, x0 + 42, y0 + 34);
  }
  ctx.restore();
}

// ---------- print texture: fine grain + faint dust, over everything ----------
let grainTile = null;
function grain(ctx, x0, y0, w, h) {
  if (!grainTile) {
    grainTile = document.createElement("canvas"); grainTile.width = grainTile.height = 256;
    const g = grainTile.getContext("2d"), im = g.createImageData(256, 256), r = rng(907);
    for (let i = 0; i < 256 * 256; i++) { const v = r(); const a = v < 0.5 ? 0 : 255; im.data[i * 4] = im.data[i * 4 + 1] = im.data[i * 4 + 2] = a; im.data[i * 4 + 3] = Math.floor(Math.abs(v - 0.5) * 2 * 60); }
    g.putImageData(im, 0, 0);
  }
  // soft-light: the grain shows on the light inks and barely touches the dark sky (as in the print)
  ctx.save(); ctx.globalCompositeOperation = "soft-light"; ctx.fillStyle = ctx.createPattern(grainTile, "repeat"); ctx.fillRect(x0, y0, w, h); ctx.restore();
}

// ---------- the hanging sign ----------
// "MIXING. / DO NOT KNOCK." on a cream board hung from a nail, drawn over the traced scene (its lettering is set in
// type: Archivo condensed, golden); board corners, screws, nail and wires measured on 117.0 s.
function sign(ctx) {
  // the hanging sign: nail, two wires, cream board, screws, lettering
  line(ctx, [[360, 358], [437, 277], [523, 333]], 2.2, HC.line);
  circle(ctx, 437, 276, 4, "#3a3034", 1.5);
  shape(ctx, [[352, 353], [531, 321], [543, 403], [367, 437]], "#f7e6d2", { lw: 3 });
  for (const [x, y] of [[362, 363], [523, 333], [533, 397], [374, 426]]) circle(ctx, x, y, 3.6, "#3a3034", 1.2);
  ctx.save(); ctx.translate(448, 380); ctx.rotate(-0.18);
  ctx.fillStyle = "#e2bb6e"; ctx.textAlign = "center";
  ctx.font = "600 27px Archivo"; ctx.fontStretch = "condensed"; ctx.letterSpacing = "0.5px";
  ctx.fillText("MIXING.", 8, -8); ctx.fillText("DO NOT KNOCK.", 0, 24);
  ctx.letterSpacing = "0px"; ctx.fontStretch = "normal"; ctx.textAlign = "left";
  ctx.restore();
}

// ----- the designer -----
// Head on his right fist, green jacket over a mustard tee, headphones round the neck, laptop, left hand on the keys.
// Everything below the lettering (y > 340) is the traced cel layer TR_DES (flat colour regions of the source at
// 117.4 s inside his silhouette, 3 skin tones, hair, beanie, 3 jacket tones, tee, laptop, headphones); only the crown
// of the beanie, which shows between the letters, is drawn here.
function designer(ctx) {
  const bean = [[946, 414], [940, 380], [944, 345], [962, 318], [1060, 298], [1160, 310], [1186, 338], [1190, 372], [1186, 402], [1150, 392], [1100, 386], [1060, 385], [1010, 390], [975, 398]];
  ctx.save(); ctx.beginPath(); ctx.rect(920, 280, 300, 72); ctx.clip();
  shape(ctx, bean, "#774c39", { lw: 3, smooth: true });
  ctx.beginPath(); smoothPath(ctx, bean, true); ctx.clip();
  ctx.strokeStyle = "rgba(40,20,12,0.45)"; ctx.lineWidth = 2;
  for (let x = 940; x < 1190; x += 7.5) { ctx.beginPath(); ctx.moveTo(x, 300); ctx.quadraticCurveTo(x + (x - 1065) * 0.06, 360, x - (x - 1065) * 0.05, 440); ctx.stroke(); }
  ctx.restore();
  drawPatch(ctx, TR_DES);
  face(ctx);
}
// His eyes, drawn crisp over the cel layer (the trace leaves the eye openings as plain skin). Measured at 8x on
// 117.4 s: upper lid (thick, tapering past the outer corner), lower lid (thin), the lid crease and the tired line
// under each eye, big brown irises (r 8.1) with a dark pupil and a catch-light.
const EYES = [
  { up: [[996.2, 434.4], [1005, 427.5], [1015, 424.4], [1025, 424], [1035, 425.6], [1040.5, 428.5]], low: [[998.7, 435], [1010, 438.1], [1022.5, 439], [1032.5, 437.5], [1038, 432.5]],
    iris: [1018.1, 431.3], hi: [1023.1, 427.5], crease: [[1003.7, 419.4], [1022.5, 415.6], [1037.5, 418]], under: [[1026, 442.5], [1033, 445.5], [1039, 445]] },
  { up: [[1090.5, 423.25], [1103, 417], [1115.5, 415.5], [1128, 417], [1136.5, 421]], low: [[1091.8, 425.1], [1103, 428.9], [1115.5, 430.1], [1128, 428], [1134.3, 423.25]],
    iris: [1111.75, 423.25], hi: [1114.25, 418.5], crease: [[1094, 411.4], [1110.5, 407.6], [1128, 410]], under: [[1093, 434.5], [1101, 437], [1110.5, 437]] },
];
function face(ctx) {
  for (const E of EYES) {
    ctx.save();
    ctx.beginPath(); smoothPath(ctx, E.up, false); const lo = E.low.slice().reverse(); for (const p of sampleCurve(lo, 6)) ctx.lineTo(p[0], p[1]); ctx.closePath();
    ctx.fillStyle = "#f4efe8"; ctx.fill(); ctx.clip();
    circle(ctx, E.iris[0], E.iris[1], 8.1, "#4a2419"); circle(ctx, E.iris[0], E.iris[1], 4.2, "#1c0d0a");
    ctx.beginPath(); ctx.arc(E.iris[0], E.iris[1], 8.1, 0, TAU); ctx.lineWidth = 1; ctx.strokeStyle = "#2a130e"; ctx.stroke();
    // the lid's shadow across the top of the eye
    ctx.fillStyle = "rgba(90,50,40,0.25)"; ctx.fillRect(E.iris[0] - 30, E.iris[1] - 14, 60, 6);
    ctx.restore();
    circle(ctx, E.hi[0], E.hi[1], 2.1, "#fdfbf6");
    taperLine(ctx, E.up, 3.6, "#1e100d");
    ctx.beginPath(); smoothPath(ctx, E.low, false); ctx.lineWidth = 1.1; ctx.strokeStyle = "rgba(95,50,40,0.8)"; ctx.lineCap = "round"; ctx.stroke();
    ctx.beginPath(); smoothPath(ctx, E.crease, false); ctx.lineWidth = 1.3; ctx.strokeStyle = "rgba(110,60,48,0.75)"; ctx.stroke();
    ctx.beginPath(); smoothPath(ctx, E.under, false); ctx.lineWidth = 1.2; ctx.strokeStyle = "rgba(140,85,70,0.6)"; ctx.stroke();
  }
}

function backdropHand(ctx) { sky(ctx); stars(ctx); ribbonsBack(ctx); clouds(ctx); }

// ---------- composition ----------
// opts: { headline: true, nav: true, grain: true, scene: true }
export function drawHippieWorld(ctx, opts = {}) {
  const { headline: withHeadline = true, nav: withNav = true, grain: withGrain = false, scene = true, x0 = WORLD_X0, x1 = WORLD_X1 } = opts;
  backdropHand(ctx);
  if (scene) {
    tiles(ctx);
    stars(ctx);
    designer(ctx);
    sign(ctx);
  }
  if (withGrain) grain(ctx, x0, -20, x1 - x0, PAGE_H + 40);
  if (withHeadline) headline(ctx);
  if (withNav) nav(ctx);
}

const cache = new Map();
function canvasOf(key, w, h, paint) {
  let c = cache.get(key);
  if (!c) {
    c = document.createElement("canvas"); c.width = w; c.height = h;
    paint(c.getContext("2d"));
    cache.set(key, c);
  }
  return c;
}
export function releaseHippie() { cache.clear(); patchPaths.clear(); skyTile = null; }

// The full colour page, 2206 x 946 (x scale for supersampling; default 1).
export function hippiePageCanvas({ headline = true, nav = true, scale = 1 } = {}) {
  return canvasOf(`page:${headline}:${nav}:${scale}`, Math.round(PAGE_W * scale), Math.round(PAGE_H * scale), (g) => {
    g.scale(scale, scale);
    drawHippieWorld(g, { headline, nav, x0: 0, x1: PAGE_W });
  });
}
// Individual layers, each 2206 x 946 in page coordinates (transparent where empty):
//   "illustration"  the whole page without headline and nav (opaque)
//   "backdrop"      the hand-built sky, stars, ribbons and clouds only (opaque) — an approximation of what is behind the
//                   gear (the page itself is traced, and its backdrop is not separable from the gear there)
//   "scene"         everything traced that is not sky: gear, boxes, plants, ribbons, clouds, the designer, the sign
//   "designer"      the designer and the middle of the desk only (transparent)
//   "headline"      the lettering with its extrusion (transparent)
//   "nav"           brand mark + the four nav pills (transparent)
export function hippieLayer(name, scale = 1) {
  const w = Math.round(PAGE_W * scale), h = Math.round(PAGE_H * scale);
  return canvasOf(`layer:${name}:${scale}`, w, h, (g) => {
    g.scale(scale, scale);
    if (name === "illustration") drawHippieWorld(g, { headline: false, nav: false, x0: 0, x1: PAGE_W });
    else if (name === "backdrop") { backdropHand(g); grain(g, 0, 0, PAGE_W, PAGE_H); }
    else if (name === "scene") { tiles(g, false); designer(g); sign(g); }
    else if (name === "designer") { drawPatch(g, TR_DK); designer(g); }
    else if (name === "headline") headline(g);
    else if (name === "nav") nav(g);
    else throw new Error(`hippieLayer: unknown layer ${name}`);
  });
}

// The page pre-shrunk to width w (halving steps, so thin lines stay clean) — for the laptop screen in the morning
// room (117.5–129 s, where the page is ~755 px wide). Aspect 2206:946.
export function hippiePageSmall(w, { headline = true, nav = true } = {}) {
  return canvasOf(`small:${w}:${headline}:${nav}`, Math.round(w), Math.round((w * PAGE_H) / PAGE_W), (g) => {
    let src = hippiePageCanvas({ headline, nav }), cw = src.width, ch = src.height;
    while (cw / 2 > w * 1.4) {
      const c = document.createElement("canvas"); c.width = Math.round(cw / 2); c.height = Math.round(ch / 2);
      const cg = c.getContext("2d"); cg.imageSmoothingQuality = "high"; cg.drawImage(src, 0, 0, c.width, c.height);
      src = c; cw = c.width; ch = c.height;
    }
    g.imageSmoothingQuality = "high";
    g.drawImage(src, 0, 0, g.canvas.width, g.canvas.height);
  });
}

// Where the colour owl perches on the page (not drawn here): the lid of the top yellow box, between its feet, at
// 117.04–117.52 s. At 117.4 s the owl covers x 1951–2108, y 65–244 (frame difference against 115.6 s).
export const OWL_PERCH = { x: 2022, y: 236 };

// The colour page's camera in the source as it arrives (s26): page → frame similarity x' = s·x + tx, y' = s·y + ty,
// measured by ORB on the lower half of the page (1000–1500 inliers). Settles to identity at 114.9 s.
export const PAGE_ARRIVAL = [
  [112.7, 0.8219, 166.7, 100.5], [112.9, 0.8288, 165.8, 101.5], [113.1, 0.8505, 147.1, 91.6], [113.3, 0.8869, 110.1, 72.4],
  [113.45, 0.9211, 70.6, 52.0], [113.6, 0.9385, 55.2, 39.3], [113.8, 0.9616, 35.8, 25.7], [114.05, 0.9792, 18.9, 13.7],
  [114.3, 0.9912, 9.0, 6.7], [114.5, 0.9953, 5.1, 2.8], [114.7, 0.9992, 0.8, 0.4], [114.9, 1, 0, 0],
];
export function pageArrival(t) {
  const A = PAGE_ARRIVAL;
  if (t <= A[0][0]) return { s: A[0][1], tx: A[0][2], ty: A[0][3] };
  for (let i = 1; i < A.length; i++) if (t <= A[i][0]) {
    const [t0, s0, x0, y0] = A[i - 1], [t1, s1, x1, y1] = A[i], u = (t - t0) / (t1 - t0);
    return { s: s0 + (s1 - s0) * u, tx: x0 + (x1 - x0) * u, ty: y0 + (y1 - y0) * u };
  }
  return { s: 1, tx: 0, ty: 0 };
}

// ---------- the header banner ----------
// The colour strip sits in the sōko page's HEADER slot (sites.js: { x: 38, y: 62, w: 2110, h: 208 }, page coordinates
// of the full-frame B&W page; on the framed screen 69.44–112 s, frame = FRAMED.{x,y} + FRAMED.{sx,sy} · page). The
// source's strip border is that rectangle (frame x 193.5–1975, y 185.3–361 at 90 s). Every shot draws the strip with
// ctx.drawImage(hippieBannerCanvas(), HEADER.x, HEADER.y, HEADER.w, HEADER.h) in page coordinates.
export const BANNER = { x: 38, y: 62, w: 2110, h: 208 };
// The strip's artwork is the colour page itself, scaled and cropped: page = S · colour + T. Measured with SIFT
// (colour page at 117.0 s ↔ the strip, 200–390 inliers, residual 0.4 px) at 88.8, 89.0, 89.5, 90, 91, 92, 93, 94, 95,
// 96, 96.8 s: colour → frame x' = 0.5887 x + 444.4 (±2.3), y' = 0.5829 y + 142.6 (±0.6); mapped back through FRAMED.
// The strip shows colour-page x −428 … 2599, y 73 … 375 (the headline, stars, the ribbons' upper runs, the cloud banks,
// box tops, the plant, the sign and the top of the beanie — no nav, no owl).
export const BANNER_MAP = { sx: 0.6972, sy: 0.6888, tx: 336.1, ty: 11.7 };
const BANNER_SS = 2;
export function hippieBannerCanvas() {
  const { x, y, w, h } = BANNER, M = BANNER_MAP;
  return canvasOf("banner", Math.round(w * BANNER_SS), Math.round(h * BANNER_SS), (g) => {
    g.scale(BANNER_SS, BANNER_SS);
    g.translate(-x, -y);
    g.translate(M.tx, M.ty); g.scale(M.sx, M.sy);
    drawHippieWorld(g, { headline: true, nav: false });
  });
}
// Draw the strip into its slot, in page coordinates, under the caller's transform.
export function drawHippieBanner(ctx, alpha = 1) {
  const c = hippieBannerCanvas();
  ctx.save(); ctx.globalAlpha *= alpha;
  ctx.drawImage(c, BANNER.x, BANNER.y, BANNER.w, BANNER.h);
  ctx.restore();
}

